#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);

    int last_seen[100001];
    for (int i = 0; i <= 100000; i++) {
        last_seen[i] = -1;
    }

    int left = 0;
    int best = 0;

    for (int i = 0; i < n; i++) {
        int value;
        scanf("%d", &value);

        if (last_seen[value] >= left) {
            left = last_seen[value] + 1;
        }

        last_seen[value] = i;

        int length = i - left + 1;
        if (length > best) {
            best = length;
        }
    }

    printf("%d\n", best);
    return 0;
}
